mapper.select:
SELECT COUNT(1)
FROM device_alarm_history ah
INNER JOIN device_info di ON ah.device_info_id = di.id
LEFT JOIN device_model dm ON di.device_model_id = dm.id
WHERE 1=1

    AND di.device_code LIKE CONCAT('%', #{deviceCode}, '%')


    AND dm.model_name = #{deviceType}


    AND ah.is_active = #{isActive}


    AND ah.start_ts >= #{startTime}


    AND ah.start_ts <= #{endTime}

SELECT di.device_code AS deviceCode, dm.model_name AS deviceType, ah.alarm_code AS alarmCode, ah.alarm_text AS alarmText, FROM_UNIXTIME(ah.start_ts / 1000, '%Y-%m-%d %H:%i:%s') AS startTime, CASE WHEN ah.end_ts IS NOT NULL THEN FROM_UNIXTIME(ah.end_ts / 1000, '%Y-%m-%d %H:%i:%s') ELSE NULL END AS endTime, ah.duration_s AS durationS, ah.is_active AS isActive FROM device_alarm_history ah INNER JOIN device_info di ON ah.device_info_id = di.id LEFT JOIN device_model dm ON di.device_model_id = dm.id WHERE 1=1
AND di.device_code LIKE CONCAT('%', #{deviceCode}, '%')
AND dm.model_name = #{deviceType}
AND ah.is_active = #{isActive}
AND ah.start_ts >= #{startTime}
AND ah.start_ts <= #{endTime}
ORDER BY ah.start_ts DESC LIMIT #{limit} OFFSET #{offset}
